80: 
81: ### Pure Core
82: 
83: ```rust
84: // crates/core/src/lib.rs
85: #![forbid(unsafe_code)]
86: 
87: use std::cmp::Ordering;
88: use std::collections::BTreeSet;
89: 
90: use serde::{Deserialize, Serialize};
91: use sha2::{Digest, Sha256};
92: use thiserror::Error;
93: 
94: const SCORE_SCALE: f64 = 1_000_000.0;
95: const ID_HEX_LENGTH: usize = 24;
96: 
97: #[derive(Debug, Clone, Deserialize)]
98: #[serde(rename_all = "camelCase")]
99: pub struct RankRequestDto {
100:     pub query: String,
101:     pub items: Vec<RankItemDto>,
102: }
103: 
104: #[derive(Debug, Clone, Deserialize)]
105: #[serde(rename_all = "camelCase")]
106: pub struct RankItemDto {
107:     pub source_id: String,
108:     pub text: String,
109:     pub score: f64,
110: }
111: 
112: #[derive(Debug, Clone)]
113: pub struct RankRequest {
114:     query: String,
115:     items: Vec<RankItem>,
116: }
117: 
118: #[derive(Debug, Clone)]
119: struct RankItem {
120:     id: String,
121:     text: String,
122:     score: FiniteScore,
123: }
124: 
125: #[derive(Debug, Clone, Serialize)]
126: #[serde(rename_all = "camelCase")]
127: pub struct RankedItem {
128:     pub id: String,
129:     pub text: String,
130:     pub score: f64,
131:     pub rank: u32,
132: }
133: 
134: #[derive(Debug, Clone, Copy)]
135: struct FiniteScore(f64);
136: 
137: impl FiniteScore {
138:     fn new(value: f64) -> Result<Self, CoreError> {
139:         if !value.is_finite() {
140:             return Err(CoreError::NonFiniteScore);
141:         }
142: 
143:         let quantized = quantize_like_math_round_six(value)?;
144:         let normalized = if quantized == 0.0 { 0.0 } else { quantized };
145:         Ok(Self(normalized))
146:     }
147: 
148:     fn get(self) -> f64 {
149:         self.0
150:     }
151: }
152: 
153: #[derive(Debug, Error)]
154: pub enum CoreError {
155:     #[error("query must not be empty")]
156:     EmptyQuery,
157: 
158:     #[error("source ID must not be empty")]
159:     EmptySourceId,
160: 
161:     #[error("score must be finite")]
162:     NonFiniteScore,
163: 
164:     #[error("score cannot be scaled without overflow")]
165:     ScoreOverflow,
166: 
167:     #[error("duplicate deterministic ID: {0}")]
168:     DuplicateId(String),
169: 
170:     #[error("result count exceeds the u32 boundary")]
171:     ResultCountOverflow,
172: }
173: 
174: impl TryFrom<RankRequestDto> for RankRequest {
175:     type Error = CoreError;
176: 
177:     fn try_from(dto: RankRequestDto) -> Result<Self, Self::Error> {
178:         if dto.query.is_empty() {
179:             return Err(CoreError::EmptyQuery);
180:         }
181: 
182:         let items = dto
183:             .items
184:             .into_iter()
185:             .map(RankItem::try_from)
186:             .collect::<Result<Vec<_>, _>>()?;
187: 
188:         Ok(Self {
189:             query: dto.query,
190:             items,
191:         })
192:     }
193: }
194: 
195: impl TryFrom<RankItemDto> for RankItem {
196:     type Error = CoreError;
197: 
198:     fn try_from(dto: RankItemDto) -> Result<Self, Self::Error> {
199:         if dto.source_id.is_empty() {
200:             return Err(CoreError::EmptySourceId);
201:         }
202: 
203:         let id = deterministic_id(&dto.source_id, &dto.text);
204:         Ok(Self {
205:             id,
206:             text: dto.text,
207:             score: FiniteScore::new(dto.score)?,
208:         })
209:     }
210: }
211: 
212: /// Ranks owned input with a complete, deterministic comparator.
213: ///
214: /// The comparator ends with a unique lowercase hexadecimal ID, protecting the
215: /// stable sort and tie-break parity contract.
216: ///
217: /// # Errors
218: ///
219: /// Returns [`CoreError`] when validation fails, IDs collide, or the result
220: /// count cannot be represented by the JavaScript boundary DTO.
221: pub fn rank_items(dto: RankRequestDto) -> Result<Vec<RankedItem>, CoreError> {
222:     let request = RankRequest::try_from(dto)?;
223:     let _query = request.query;
224: 
225:     let mut seen = BTreeSet::new();
226:     for item in &request.items {
227:         if !seen.insert(item.id.clone()) {
228:             return Err(CoreError::DuplicateId(item.id.clone()));
229:         }
230:     }
231: 
232:     let mut items = request.items;
233:     items.sort_by(compare_rank_items);
234: 
235:     items
236:         .into_iter()
237:         .enumerate()
238:         .map(|(index, item)| {
239:             let rank = u32::try_from(index)
240:                 .map_err(|_| CoreError::ResultCountOverflow)?
241:                 .checked_add(1)
242:                 .ok_or(CoreError::ResultCountOverflow)?;
243: 
244:             Ok(RankedItem {
245:                 id: item.id,
246:                 text: item.text,
247:                 score: item.score.get(),
248:                 rank,
249:             })
250:         })
251:         .collect()
252: }
253: 
254: fn compare_rank_items(left: &RankItem, right: &RankItem) -> Ordering {
255:     right
256:         .score
257:         .get()
258:         .total_cmp(&left.score.get())
259:         .then_with(|| left.id.cmp(&right.id))
260: }
261: 
262: fn quantize_like_math_round_six(value: f64) -> Result<f64, CoreError> {
263:     if !value.is_finite() {
264:         return Err(CoreError::NonFiniteScore);
265:     }
266: 
267:     let scaled = value * SCORE_SCALE;
268:     if !scaled.is_finite() {
269:         return Err(CoreError::ScoreOverflow);
270:     }
271: 
272:     let floor = scaled.floor();
273:     let fraction = scaled - floor;
274:     let rounded = if fraction < 0.5 { floor } else { floor + 1.0 };
275:     let signed = if rounded == 0.0 && scaled.is_sign_negative() {
276:         -0.0
277:     } else {
278:         rounded
279:     };
280: 
281:     Ok(signed / SCORE_SCALE)
282: }
283: 
284: fn deterministic_id(source_id: &str, text: &str) -> String {
285:     let mut hasher = Sha256::new();
286: 
287:     // Field order and delimiters are part of the deterministic-ID parity contract.
288:     hasher.update(b"rank-item\0");
289:     hasher.update(source_id.as_bytes());
290:     hasher.update(b"\0");
291:     hasher.update(text.as_bytes());
292: 
293:     let digest = hasher.finalize();
294:     hex::encode(digest).chars().take(ID_HEX_LENGTH).collect()
295: }
296: ```
