298: ### Thin napi-rs Adapter
299: 
300: ```rust
301: // crates/napi/src/lib.rs
302: #![deny(unsafe_op_in_unsafe_fn)]
303: 
304: use napi::bindgen_prelude::AsyncTask;
305: use napi::{Env, Error, Result, Status, Task};
306: use napi_derive::napi;
307: use ranking_core::{
308:     rank_items as rank_core, CoreError, RankItemDto as CoreRankItemDto,
309:     RankRequestDto as CoreRankRequestDto, RankedItem as CoreRankedItem,
310: };
311: 
312: #[napi(object)]
313: pub struct RankItemDto {
314:     pub source_id: String,
315:     pub text: String,
316:     pub score: f64,
317: }
318: 
319: #[napi(object)]
320: pub struct RankRequestDto {
321:     pub query: String,
322:     pub items: Vec<RankItemDto>,
323: }
324: 
325: #[napi(object)]
326: pub struct RankedItemDto {
327:     pub id: String,
328:     pub text: String,
329:     pub score: f64,
330:     pub rank: u32,
331: }
332: 
333: impl From<RankRequestDto> for CoreRankRequestDto {
334:     fn from(dto: RankRequestDto) -> Self {
335:         Self {
336:             query: dto.query,
337:             items: dto
338:                 .items
339:                 .into_iter()
340:                 .map(|item| CoreRankItemDto {
341:                     source_id: item.source_id,
342:                     text: item.text,
343:                     score: item.score,
344:                 })
345:                 .collect(),
346:         }
347:     }
348: }
349: 
350: impl From<CoreRankedItem> for RankedItemDto {
351:     fn from(item: CoreRankedItem) -> Self {
352:         Self {
353:             id: item.id,
354:             text: item.text,
355:             score: item.score,
356:             rank: item.rank,
357:         }
358:     }
359: }
360: 
361: fn to_napi_error(error: CoreError) -> Error {
362:     let (status, code) = match error {
363:         CoreError::EmptyQuery | CoreError::EmptySourceId => {
364:             (Status::InvalidArg, "INVALID_PARAMETER")
365:         }
366:         CoreError::NonFiniteScore | CoreError::ScoreOverflow => {
367:             (Status::InvalidArg, "INVALID_SCORE")
368:         }
369:         CoreError::DuplicateId(_) => (Status::GenericFailure, "DUPLICATE_ID"),
370:         CoreError::ResultCountOverflow => (Status::GenericFailure, "RESULT_OVERFLOW"),
371:     };
372: 
373:     Error::new(status, format!("{code}: {error}"))
374: }
375: 
376: fn execute(input: RankRequestDto) -> Result<Vec<RankedItemDto>> {
377:     rank_core(input.into())
378:         .map(|items| items.into_iter().map(RankedItemDto::from).collect())
379:         .map_err(to_napi_error)
380: }
381: 
382: #[napi(js_name = "rankItems")]
383: pub fn rank_items(input: RankRequestDto) -> Result<Vec<RankedItemDto>> {
384:     execute(input)
385: }
386: 
387: pub struct RankTask {
388:     input: Option<RankRequestDto>,
389: }
390: 
391: impl Task for RankTask {
392:     type Output = Vec<CoreRankedItem>;
393:     type JsValue = Vec<RankedItemDto>;
394: 
395:     fn compute(&mut self) -> Result<Self::Output> {
396:         let input = self.input.take().ok_or_else(|| {
397:             Error::new(Status::GenericFailure, "INTERNAL_STATE: task input missing")
398:         })?;
399: 
400:         rank_core(input.into()).map_err(to_napi_error)
401:     }
402: 
403:     fn resolve(&mut self, _env: Env, output: Self::Output) -> Result<Self::JsValue> {
404:         Ok(output.into_iter().map(RankedItemDto::from).collect())
405:     }
406: }
407: 
408: #[napi(js_name = "rankItemsAsync")]
409: pub fn rank_items_async(input: RankRequestDto) -> AsyncTask<RankTask> {
410:     // Only owned Rust data enters the worker; no Env or JavaScript handle crosses threads.
411:     AsyncTask::new(RankTask { input: Some(input) })
412: }
413: ```
414: 
415: The synchronous export returns `napi::Result<T>`. Use `AsyncTask` only for measured CPU or blocking work that would materially block Node. Convert JavaScript values into owned Rust DTOs before `compute`; JavaScript handles and `Env` remain on the JavaScript thread.
416: 
417: ### Thin wasm-bindgen Adapter
418: 
419: ```rust
420: // crates/wasm/src/lib.rs
421: #![deny(unsafe_op_in_unsafe_fn)]
422: 
423: use js_sys::{Error as JsError, Reflect};
424: use ranking_core::{rank_items as rank_core, CoreError, RankRequestDto};
425: use serde::Serialize;
426: use wasm_bindgen::prelude::*;
427: 
428: #[wasm_bindgen(js_name = rankItems)]
429: pub fn rank_items(input: JsValue) -> Result<JsValue, JsValue> {
430:     let request: RankRequestDto = serde_wasm_bindgen::from_value(input)
431:         .map_err(|error| js_error("INVALID_PARAMETER", &error.to_string()))?;
432: 
433:     let output = rank_core(request)
434:         .map_err(core_error_to_js)?;
435: 
436:     let serializer = serde_wasm_bindgen::Serializer::json_compatible();
437:     output
438:         .serialize(&serializer)
439:         .map_err(|error| js_error("SERIALIZATION_FAILED", &error.to_string()))
440: }
441: 
442: fn core_error_to_js(error: CoreError) -> JsValue {
443:     let code = match error {
444:         CoreError::EmptyQuery | CoreError::EmptySourceId => "INVALID_PARAMETER",
445:         CoreError::NonFiniteScore | CoreError::ScoreOverflow => "INVALID_SCORE",
446:         CoreError::DuplicateId(_) => "DUPLICATE_ID",
447:         CoreError::ResultCountOverflow => "RESULT_OVERFLOW",
448:     };
449: 
450:     js_error(code, &error.to_string())
451: }
452: 
453: fn js_error(code: &str, message: &str) -> JsValue {
454:     let error = JsError::new(message);
455: 
456:     // A newly created Error is extensible; setting code preserves the JS error-shape contract.
457:     let _set_result = Reflect::set(
458:         error.as_ref(),
459:         &JsValue::from_str("code"),
460:         &JsValue::from_str(code),
461:     );
462: 
463:     error.into()
464: }
465: ```
466: 
467: Keep serializer configuration explicit. `Serializer::json_compatible()` produces JavaScript-compatible values, but exact field order, omission behavior, integer representation, and number spelling still require golden tests against the TypeScript oracle.
