41: | Thin boundaries | Pure Rust core plus transport-only adapters | DTO/ABI and JavaScript error-shape parity |
42: | Byte parity | Compare exact TypeScript and Rust output bytes | Serialized-output parity |
43: | Separate numeric helpers | Preserve each TypeScript rounding operation independently | Six-decimal score parity |
44: | Complete ordering | End every observable comparator with a deterministic unique key | Stable sort and tie-break parity |
45: | Exact IDs | Preserve preimage fields, order, delimiters, UTF-8, hash, encoding, and truncation | Deterministic-ID parity |
46: | Canonical collections | Use `BTreeMap`, `BTreeSet`, or explicit sorting before output | Deterministic hash and iteration order |
47: | No boundary panic | Map recoverable failures through typed `Result` values | Node process survival, WASM trap avoidance, and error-shape parity |
48: | Reviewed unsafe | Adjacent `// SAFETY:` invariant, safe wrapper, and tests | FFI memory safety and boundary integrity |
49: 
50: The release assertion is byte-oriented:
51: 
52: ```rust
53: assert_eq!(
54:     typescript_oracle_bytes,
55:     rust_boundary_bytes,
56:     "semantic equality does not satisfy the parity contract",
57: );
58: ```
59: 
60: ---
61: 
62: ## 2. COMPLETE RUST BOUNDARY MODULE TEMPLATE
63: 
64: Use a workspace with a pure core and separate napi-rs and wasm-bindgen adapters:
65: 
66: ```text
67: Cargo.toml
68: Cargo.lock
69: crates/
70:   core/
71:     Cargo.toml
72:     src/lib.rs
73:   napi/
74:     Cargo.toml
75:     src/lib.rs
76:   wasm/
77:     Cargo.toml
78:     src/lib.rs
79: ```
80: 
81: ### Pure Core
82: 
83: ```rust
84: // crates/core/src/lib.rs
85: #![forbid(unsafe_code)]
86: 
87: use std::cmp::Ordering;
88: use std::collections::BTreeSet;
89: 
90: use serde::{Deserialize, Serialize};
91: use sha2::{Digest, Sha256};
92: use thiserror::Error;
93: 
94: const SCORE_SCALE: f64 = 1_000_000.0;
95: const ID_HEX_LENGTH: usize = 24;
96: 
97: #[derive(Debug, Clone, Deserialize)]
98: #[serde(rename_all = "camelCase")]
99: pub struct RankRequestDto {
100:     pub query: String,
101:     pub items: Vec<RankItemDto>,
102: }
103: 
104: #[derive(Debug, Clone, Deserialize)]
105: #[serde(rename_all = "camelCase")]
106: pub struct RankItemDto {
107:     pub source_id: String,
108:     pub text: String,
109:     pub score: f64,
110: }
111: 
112: #[derive(Debug, Clone)]
113: pub struct RankRequest {
114:     query: String,
115:     items: Vec<RankItem>,
116: }
117: 
118: #[derive(Debug, Clone)]
119: struct RankItem {
120:     id: String,
121:     text: String,
122:     score: FiniteScore,
123: }
124: 
125: #[derive(Debug, Clone, Serialize)]
126: #[serde(rename_all = "camelCase")]
127: pub struct RankedItem {
128:     pub id: String,
129:     pub text: String,
130:     pub score: f64,
131:     pub rank: u32,
132: }
133: 
134: #[derive(Debug, Clone, Copy)]
135: struct FiniteScore(f64);
136: 
137: impl FiniteScore {
138:     fn new(value: f64) -> Result<Self, CoreError> {
139:         if !value.is_finite() {
140:             return Err(CoreError::NonFiniteScore);
141:         }
142: 
143:         let quantized = quantize_like_math_round_six(value)?;
144:         let normalized = if quantized == 0.0 { 0.0 } else { quantized };
145:         Ok(Self(normalized))
146:     }
147: 
148:     fn get(self) -> f64 {
149:         self.0
150:     }
151: }
152: 
153: #[derive(Debug, Error)]
154: pub enum CoreError {
155:     #[error("query must not be empty")]
156:     EmptyQuery,
157: 
158:     #[error("source ID must not be empty")]
159:     EmptySourceId,
160: 
161:     #[error("score must be finite")]
162:     NonFiniteScore,
163: 
164:     #[error("score cannot be scaled without overflow")]
165:     ScoreOverflow,
166: 
167:     #[error("duplicate deterministic ID: {0}")]
168:     DuplicateId(String),
169: 
170:     #[error("result count exceeds the u32 boundary")]
171:     ResultCountOverflow,
172: }
173: 
174: impl TryFrom<RankRequestDto> for RankRequest {
175:     type Error = CoreError;
176: 
177:     fn try_from(dto: RankRequestDto) -> Result<Self, Self::Error> {
178:         if dto.query.is_empty() {
179:             return Err(CoreError::EmptyQuery);
180:         }
181: 
182:         let items = dto
183:             .items
184:             .into_iter()
185:             .map(RankItem::try_from)
186:             .collect::<Result<Vec<_>, _>>()?;
187: 
188:         Ok(Self {
189:             query: dto.query,
190:             items,
191:         })
192:     }
193: }
194: 
195: impl TryFrom<RankItemDto> for RankItem {
196:     type Error = CoreError;
197: 
198:     fn try_from(dto: RankItemDto) -> Result<Self, Self::Error> {
199:         if dto.source_id.is_empty() {
200:             return Err(CoreError::EmptySourceId);
201:         }
202: 
203:         let id = deterministic_id(&dto.source_id, &dto.text);
204:         Ok(Self {
205:             id,
206:             text: dto.text,
207:             score: FiniteScore::new(dto.score)?,
208:         })
209:     }
210: }
211: 
212: /// Ranks owned input with a complete, deterministic comparator.
213: ///
214: /// The comparator ends with a unique lowercase hexadecimal ID, protecting the
215: /// stable sort and tie-break parity contract.
216: ///
217: /// # Errors
218: ///
219: /// Returns [`CoreError`] when validation fails, IDs collide, or the result
220: /// count cannot be represented by the JavaScript boundary DTO.
221: pub fn rank_items(dto: RankRequestDto) -> Result<Vec<RankedItem>, CoreError> {
222:     let request = RankRequest::try_from(dto)?;
223:     let _query = request.query;
224: 
225:     let mut seen = BTreeSet::new();
226:     for item in &request.items {
227:         if !seen.insert(item.id.clone()) {
228:             return Err(CoreError::DuplicateId(item.id.clone()));
229:         }
230:     }
231: 
232:     let mut items = request.items;
233:     items.sort_by(compare_rank_items);
234: 
235:     items
236:         .into_iter()
237:         .enumerate()
238:         .map(|(index, item)| {
239:             let rank = u32::try_from(index)
240:                 .map_err(|_| CoreError::ResultCountOverflow)?
241:                 .checked_add(1)
242:                 .ok_or(CoreError::ResultCountOverflow)?;
243: 
244:             Ok(RankedItem {
245:                 id: item.id,
246:                 text: item.text,
247:                 score: item.score.get(),
248:                 rank,
249:             })
250:         })
251:         .collect()
252: }
253: 
254: fn compare_rank_items(left: &RankItem, right: &RankItem) -> Ordering {
255:     right
256:         .score
257:         .get()
258:         .total_cmp(&left.score.get())
259:         .then_with(|| left.id.cmp(&right.id))
260: }
261: 
262: fn quantize_like_math_round_six(value: f64) -> Result<f64, CoreError> {
263:     if !value.is_finite() {
264:         return Err(CoreError::NonFiniteScore);
265:     }
266: 
267:     let scaled = value * SCORE_SCALE;
268:     if !scaled.is_finite() {
269:         return Err(CoreError::ScoreOverflow);
270:     }
271: 
272:     let floor = scaled.floor();
273:     let fraction = scaled - floor;
274:     let rounded = if fraction < 0.5 { floor } else { floor + 1.0 };
275:     let signed = if rounded == 0.0 && scaled.is_sign_negative() {
276:         -0.0
277:     } else {
278:         rounded
279:     };
280: 
281:     Ok(signed / SCORE_SCALE)
282: }
283: 
284: fn deterministic_id(source_id: &str, text: &str) -> String {
285:     let mut hasher = Sha256::new();
286: 
287:     // Field order and delimiters are part of the deterministic-ID parity contract.
288:     hasher.update(b"rank-item\0");
289:     hasher.update(source_id.as_bytes());
290:     hasher.update(b"\0");
291:     hasher.update(text.as_bytes());
292: 
293:     let digest = hasher.finalize();
294:     hex::encode(digest).chars().take(ID_HEX_LENGTH).collect()
295: }
296: ```
297: 
298: ### Thin napi-rs Adapter
299: 
300: ```rust
301: // crates/napi/src/lib.rs
302: #![deny(unsafe_op_in_unsafe_fn)]
303: 
304: use napi::bindgen_prelude::AsyncTask;
305: use napi::{Env, Error, Result, Status, Task};
306: use napi_derive::napi;
307: use ranking_core::{
308:     rank_items as rank_core, CoreError, RankItemDto as CoreRankItemDto,
309:     RankRequestDto as CoreRankRequestDto, RankedItem as CoreRankedItem,
310: };
311: 
312: #[napi(object)]
313: pub struct RankItemDto {
314:     pub source_id: String,
315:     pub text: String,
316:     pub score: f64,
317: }
318: 
319: #[napi(object)]
320: pub struct RankRequestDto {
321:     pub query: String,
322:     pub items: Vec<RankItemDto>,
323: }
324: 
325: #[napi(object)]
326: pub struct RankedItemDto {
327:     pub id: String,
328:     pub text: String,
329:     pub score: f64,
330:     pub rank: u32,
331: }
332: 
333: impl From<RankRequestDto> for CoreRankRequestDto {
334:     fn from(dto: RankRequestDto) -> Self {
335:         Self {
336:             query: dto.query,
337:             items: dto
338:                 .items
339:                 .into_iter()
340:                 .map(|item| CoreRankItemDto {
341:                     source_id: item.source_id,
342:                     text: item.text,
343:                     score: item.score,
344:                 })
345:                 .collect(),
346:         }
347:     }
348: }
349: 
350: impl From<CoreRankedItem> for RankedItemDto {
351:     fn from(item: CoreRankedItem) -> Self {
352:         Self {
353:             id: item.id,
354:             text: item.text,
355:             score: item.score,
356:             rank: item.rank,
357:         }
358:     }
359: }
360: 
361: fn to_napi_error(error: CoreError) -> Error {
362:     let (status, code) = match error {
363:         CoreError::EmptyQuery | CoreError::EmptySourceId => {
364:             (Status::InvalidArg, "INVALID_PARAMETER")
365:         }
366:         CoreError::NonFiniteScore | CoreError::ScoreOverflow => {
367:             (Status::InvalidArg, "INVALID_SCORE")
368:         }
369:         CoreError::DuplicateId(_) => (Status::GenericFailure, "DUPLICATE_ID"),
370:         CoreError::ResultCountOverflow => (Status::GenericFailure, "RESULT_OVERFLOW"),
371:     };
372: 
373:     Error::new(status, format!("{code}: {error}"))
374: }
375: 
376: fn execute(input: RankRequestDto) -> Result<Vec<RankedItemDto>> {
377:     rank_core(input.into())
378:         .map(|items| items.into_iter().map(RankedItemDto::from).collect())
379:         .map_err(to_napi_error)
380: }
381: 
382: #[napi(js_name = "rankItems")]
383: pub fn rank_items(input: RankRequestDto) -> Result<Vec<RankedItemDto>> {
384:     execute(input)
385: }
386: 
387: pub struct RankTask {
388:     input: Option<RankRequestDto>,
389: }
390: 
391: impl Task for RankTask {
392:     type Output = Vec<CoreRankedItem>;
393:     type JsValue = Vec<RankedItemDto>;
394: 
395:     fn compute(&mut self) -> Result<Self::Output> {
396:         let input = self.input.take().ok_or_else(|| {
397:             Error::new(Status::GenericFailure, "INTERNAL_STATE: task input missing")
398:         })?;
399: 
400:         rank_core(input.into()).map_err(to_napi_error)
401:     }
402: 
403:     fn resolve(&mut self, _env: Env, output: Self::Output) -> Result<Self::JsValue> {
404:         Ok(output.into_iter().map(RankedItemDto::from).collect())
405:     }
406: }
407: 
408: #[napi(js_name = "rankItemsAsync")]
409: pub fn rank_items_async(input: RankRequestDto) -> AsyncTask<RankTask> {
410:     // Only owned Rust data enters the worker; no Env or JavaScript handle crosses threads.
411:     AsyncTask::new(RankTask { input: Some(input) })
412: }
413: ```
414: 
415: The synchronous export returns `napi::Result<T>`. Use `AsyncTask` only for measured CPU or blocking work that would materially block Node. Convert JavaScript values into owned Rust DTOs before `compute`; JavaScript handles and `Env` remain on the JavaScript thread.
416: 
417: ### Thin wasm-bindgen Adapter
418: 
419: ```rust
420: // crates/wasm/src/lib.rs
421: #![deny(unsafe_op_in_unsafe_fn)]
422: 
423: use js_sys::{Error as JsError, Reflect};
424: use ranking_core::{rank_items as rank_core, CoreError, RankRequestDto};
425: use serde::Serialize;
426: use wasm_bindgen::prelude::*;
427: 
428: #[wasm_bindgen(js_name = rankItems)]
429: pub fn rank_items(input: JsValue) -> Result<JsValue, JsValue> {
430:     let request: RankRequestDto = serde_wasm_bindgen::from_value(input)
431:         .map_err(|error| js_error("INVALID_PARAMETER", &error.to_string()))?;
432: 
433:     let output = rank_core(request)
434:         .map_err(core_error_to_js)?;
435: 
436:     let serializer = serde_wasm_bindgen::Serializer::json_compatible();
437:     output
438:         .serialize(&serializer)
439:         .map_err(|error| js_error("SERIALIZATION_FAILED", &error.to_string()))
440: }
441: 
442: fn core_error_to_js(error: CoreError) -> JsValue {
443:     let code = match error {
444:         CoreError::EmptyQuery | CoreError::EmptySourceId => "INVALID_PARAMETER",
445:         CoreError::NonFiniteScore | CoreError::ScoreOverflow => "INVALID_SCORE",
446:         CoreError::DuplicateId(_) => "DUPLICATE_ID",
447:         CoreError::ResultCountOverflow => "RESULT_OVERFLOW",
448:     };
449: 
450:     js_error(code, &error.to_string())
451: }
452: 
453: fn js_error(code: &str, message: &str) -> JsValue {
454:     let error = JsError::new(message);
455: 
456:     // A newly created Error is extensible; setting code preserves the JS error-shape contract.
457:     let _set_result = Reflect::set(
458:         error.as_ref(),
459:         &JsValue::from_str("code"),
460:         &JsValue::from_str(code),
461:     );
462: 
463:     error.into()
464: }
465: ```
466: 
467: Keep serializer configuration explicit. `Serializer::json_compatible()` produces JavaScript-compatible values, but exact field order, omission behavior, integer representation, and number spelling still require golden tests against the TypeScript oracle.
